#include <bits/stdc++.h>
#define MOD 1000000007LL
using namespace std;
typedef long long ll;
const int MAXK = 30;
const int MAXLOG = 200;

ll N, K;
struct matrix { ll d[MAXK][MAXK]; };
struct vector_ { ll d[MAXK]; };
matrix M[MAXK], MI[MAXK];
matrix E[MAXLOG][MAXK], EI[MAXLOG][MAXK];
vector_ cur;

ll val(ll x) {
    if (x < K) return x;
    return (x + val(x / K)) % K;
}

matrix mul(const matrix& a, const matrix& b) {
    matrix c;
    for (int i = 0; i < K; ++i) {
        for (int j = 0; j < K; ++j) {
            ll s = 0;
            for (int l = 0; l < K; ++l)
                s = (s + a.d[i][l] * b.d[l][j]) % MOD;
            c.d[i][j] = s;
        }
    }
    return c;
}

vector_ mul(const matrix& a, const vector_& b) {
    vector_ c;
    for (int i = 0; i < K; ++i) {
        ll s = 0;
        for (int j = 0; j < K; ++j)
            s = (s + b.d[j] * a.d[i][j]) % MOD;
        c.d[i] = s;
    }
    return c;
}

void precompute() {
    for (int i = 0; i < K; ++i) {
        E[0][i] = M[i];
        EI[0][i] = MI[i];
    }
    int LOG = 0;
    ll t = N;
    while (t) { ++LOG; t /= K; }
    for (int j = 1; j <= LOG; ++j) {
        E[j][0] = E[j-1][0];
        EI[j][0] = EI[j-1][0];
        for (int l = 1; l < K; ++l) {
            E[j][0] = mul(E[j-1][l], E[j][0]);
            EI[j][0] = mul(EI[j][0], EI[j-1][l]);
        }
        for (int i = 1; i < K; ++i) {
            E[j][i] = mul(E[j-1][i-1], mul(E[j][i-1], EI[j-1][i-1]));
            EI[j][i] = mul(E[j-1][i-1], mul(EI[j][i-1], EI[j-1][i-1]));
        }
    }
}

vector_ solve(ll n, vector_ v, int depth) {
    if (n == 0) return v;
    int w = val(n / K);
    v = solve(n / K, v, depth + 1);
    for (int i = 0; i < n % K; ++i)
        v = mul(E[depth][(w + i) % K], v);
    return v;
}

int main() {
    scanf("%lld %lld", &N, &K);
    for (int i = 0; i < K; ++i) {
        cur.d[i] = 1;
        for (int j = 0; j < K; ++j) {
            for (int l = 0; l < K; ++l) {
                if (j == l) {
                    M[i].d[j][l] = 1;
                    MI[i].d[j][l] = 1;
                } else if (j == i) {
                    M[i].d[j][l] = 1;
                    MI[i].d[j][l] = -1;
                } else {
                    M[i].d[j][l] = 0;
                    MI[i].d[j][l] = 0;
                }
            }
        }
    }
    precompute();
    cur = solve(N, cur, 0);
    ll tot = 0;
    for (int i = 0; i < K; ++i) tot += cur.d[i];
    --tot;
    tot %= MOD;
    if (tot < 0) tot += MOD;
    while (tot % (K - 1) != 0) tot += MOD;
    printf("%lld\n", tot / (K - 1));
    return 0;
}
